interface Payable {
    double calculateAmount();

    default String describe() {
        return "Amount due: " + calculateAmount();
    }
}

class Invoice implements Payable {
    private final double baseAmount;
    private final double taxRate;

    Invoice(double baseAmount, double taxRate) {
        this.baseAmount = baseAmount;
        this.taxRate = taxRate;
    }

    @Override
    public double calculateAmount() {
        return baseAmount * (1 + taxRate);
    }
}

interface Validator<T> {
    boolean isValid(T value);

    // default: them hanh vi moi ma khong pha class da implement
    default Validator<T> and(Validator<T> other) {
        return value -> this.isValid(value) && other.isValid(value);
    }

    // static: ham tien ich, KHONG duoc ke thua boi class implement
    static Validator<String> notBlank() {
        return s -> s != null && !s.isBlank();
    }
}

class MaxLength implements Validator<String> {
    private final int max;
    MaxLength(int max) { this.max = max; }
    @Override public boolean isValid(String value) { return value.length() <= max; }
}

class ValidatorDemo {
    public static void main(String[] args) {
        Validator<String> rule = Validator.notBlank().and(new MaxLength(5));
        System.out.println(rule.isValid("abc"));      // true
        System.out.println(rule.isValid("  "));        // false
        System.out.println(rule.isValid("abcdefgh")); // false
    }
}

class Outer {
    private int state = 42;

    static class Nested {                 // khong giu tham chieu Outer
        int compute() { return 1; }
    }

    class Inner {                          // giu tham chieu Outer ngam
        int read() { return state; }        // truy cap duoc field private cua Outer
    }

    Runnable localAndAnonymous() {
        int captured = 10;                 // phai la effectively final
        class Local { int twice() { return captured * 2; } }
        Local local = new Local();
        return new Runnable() {            // anonymous class
            @Override public void run() {
                System.out.println(state + local.twice());
            }
        };
    }

    public static void main(String[] args) {
        Nested n = new Outer.Nested();          // khong can Outer instance
        Outer outer = new Outer();
        Inner in = outer.new Inner();           // cu phap bat buoc co instance
        outer.localAndAnonymous().run();        // 62
        System.out.println(n.compute() + in.read());
    }
}

enum OrderStatus {
    NEW(false), PAID(false), SHIPPED(true), CANCELLED(true);

    private final boolean terminal;                 // state rieng cho moi hang so
    OrderStatus(boolean terminal) { this.terminal = terminal; }
    boolean isTerminal() { return terminal; }

    // hanh vi khac nhau theo tung hang so bang cach override
    OrderStatus next() {
        return switch (this) {                       // switch tren enum: khong can qualify
            case NEW -> PAID;
            case PAID -> SHIPPED;
            case SHIPPED, CANCELLED -> this;
        };
    }

    public static void main(String[] args) {
        OrderStatus s = OrderStatus.valueOf("NEW"); // nem IllegalArgumentException neu sai
        System.out.println(s.next());                // PAID
        System.out.println(s.ordinal() + " " + s.name());
        // EnumMap/EnumSet: cau truc du lieu toi uu rieng cho enum
        java.util.EnumSet<OrderStatus> open = java.util.EnumSet.of(NEW, PAID);
        System.out.println(open.contains(SHIPPED)); // false
    }
}

